"""Academic-only image galleries and a browser-local mesh viewer."""
from pathlib import Path
from html import escape
import json

FIGURES=json.loads((Path(__file__).resolve().parent.parent/'assets/gallery/catalog.json').read_text(encoding='utf-8'))
GROUPS={'handling':('Academic CAD design','Akademische CAD-Konstruktion'),'ansys':('ANSYS training','ANSYS-Training'),'frost':('Frost modelling','Frostmodellierung'),'thesis':('Thesis charts & method','Thesis: Diagramme & Methode'),'shoe':('Manufacturing plans','Fertigungsplanung')}

def gallery_strip(project,lang):
    figures=[f for f in FIGURES if f['group']==project]
    if not figures:return ''
    en=lang=='en';links=''
    for f in figures[:4]:
        caption=f[lang]+' · '+f['source']+' · p. '+str(f['page'])
        links+=f'<a href="/assets/gallery/{f["key"]}.webp" data-viewer data-caption="{escape(caption,quote=True)}"><img src="/assets/gallery/{f["key"]}.webp" alt="{escape(caption,quote=True)}" loading="lazy" width="180" height="120"></a>'
    return f'<div class="project-gallery-strip">{links}</div><a class="text-link" href="/{lang}/gallery/?project={project}">{("Explore all "+str(len(figures))+" figures") if en else ("Alle "+str(len(figures))+" Abbildungen ansehen")} ↗</a>'

def gallery_intro(lang):
    en=lang=='en'
    return f'''<section class="section gallery-intro" id="academic-gallery"><div class="section-heading"><div><p class="eyebrow">ACADEMIC DESIGN / ANALYSIS / RESEARCH</p><h2>{'See the work.<br>Explore the details.' if en else 'Arbeit sehen.<br>Details entdecken.'}</h2></div><p>{len(FIGURES)} {'selected figures from academic design, simulation exercises, numerical modelling and thesis charts. Employer CAD, equipment photographs and real hardware models are excluded.' if en else 'ausgewählte Abbildungen aus akademischer Konstruktion, Simulationsübungen, numerischer Modellierung und Thesis-Diagrammen. Arbeitgeber-CAD, Anlagenfotos und reale Hardwaremodelle sind ausgeschlossen.'}</p></div><div class="gallery-highlights">{''.join(f'<a href="/{lang}/gallery/?project={group}"><img src="/assets/gallery/{next(f["key"] for f in FIGURES if f["group"]==group)}.webp" alt="{GROUPS[group][0 if en else 1]}" loading="lazy" width="420" height="250"><span>{GROUPS[group][0 if en else 1]} ↗</span></a>' for group in ['handling','ansys','thesis'])}</div><div class="proof-bottom"><a class="button primary" href="/{lang}/gallery/">{'Open academic gallery' if en else 'Akademische Galerie öffnen'} ↗</a><a class="text-link" href="/{lang}/cad/">{'Open a CAD mesh from your device' if en else 'CAD-Netz vom eigenen Gerät öffnen'} ↗</a></div></section>'''

def gallery_page(lang,head,footer,copy,viewer):
    en=lang=='en';title='Academic project gallery' if en else 'Akademische Projektgalerie'
    cards=''
    for f in FIGURES:
        caption=f[lang]+' · '+f['source']+' · p. '+str(f['page'])
        cards+=f'''<article class="gallery-card" data-gallery-group="{f['group']}" id="{f['key']}"><a href="/assets/gallery/{f['key']}.webp" data-viewer data-caption="{escape(caption,quote=True)}"><img src="/assets/gallery/{f['key']}.webp" alt="{escape(caption,quote=True)}" loading="lazy" width="{f['width']}" height="{f['height']}"><span>{'Enlarge' if en else 'Vergrößern'} ↗</span></a><div><p class="eyebrow">{GROUPS[f['group']][0 if en else 1]}</p><h2>{f[lang]}</h2><p>{f['source']} · {'page' if en else 'Seite'} {f['page']}</p></div></article>'''
    options=''.join(f'<button type="button" data-gallery-filter="{key}" aria-pressed="false">{labels[0 if en else 1]}</button>' for key,labels in GROUPS.items())
    return head(lang,copy,title+' | Sagar Kriplani',f'/{lang}/gallery/')+f'''<main id="main" class="evidence-page"><div class="library-heading"><a class="text-link" href="/{lang}/#work">← {'Back to projects' if en else 'Zurück zu den Projekten'}</a><p class="eyebrow">ACADEMIC PROJECTS / SOURCE FIGURES</p><h1>{'The details behind<br>the design.' if en else 'Die Details hinter<br>der Konstruktion.'}</h1><p>{len(FIGURES)} {'selected academic source figures. Filter by project, then enlarge, zoom and compare the original views. These are report excerpts, not interactive source CAD.' if en else 'ausgewählte akademische Originalabbildungen. Nach Projekt filtern, vergrößern und Ansichten vergleichen. Es handelt sich um Berichtsauszüge, nicht um interaktive CAD-Quelldaten.'}</p></div><aside class="evidence-policy"><strong>{'Academic work, with context' if en else 'Akademische Arbeit mit Einordnung'}</strong><p>{'The mechanism is an academic CAD design. ANSYS images are training exercises. Frost and diploma work are team projects. Thesis charts retain their experimental limitations. No Brooks CAD, equipment photographs, chamber models or source CAD files are published here.' if en else 'Der Mechanismus ist eine akademische CAD-Konstruktion. ANSYS-Bilder zeigen Trainingsaufgaben. Frost- und Diplomarbeiten sind Teamprojekte. Für Thesis-Diagramme gelten die experimentellen Einschränkungen. Brooks-CAD, Anlagenfotos, Kammermodelle und CAD-Quelldateien werden hier nicht veröffentlicht.'}</p></aside><div class="filters" role="group" aria-label="{'Filter academic figures' if en else 'Akademische Abbildungen filtern'}"><button type="button" data-gallery-filter="all" aria-pressed="true">{'All figures' if en else 'Alle Abbildungen'}</button>{options}</div><p class="gallery-status" role="status" aria-live="polite">{len(FIGURES)} {'figures' if en else 'Abbildungen'}</p><div class="academic-gallery-grid">{cards}</div><div class="gallery-more"><button class="button primary" id="gallery-more" type="button" hidden>{'Show more figures' if en else 'Weitere Abbildungen anzeigen'} ↓</button></div><p class="source">{'This gallery does not establish manufacturing validation or independent experimental replication. Source labels identify each excerpt’s context.' if en else 'Die Galerie belegt keine Fertigungsvalidierung oder unabhängige experimentelle Replikation. Quellenangaben ordnen jeden Auszug ein.'}</p><div class="proof-bottom"><a class="button primary" href="/{lang}/cad/">{'View a mesh from your device' if en else 'Netz vom eigenen Gerät ansehen'} ↗</a></div></main>'''+viewer(lang)+footer(lang,copy)

def cad_page(lang,head,footer,copy):
    en=lang=='en';title='Local CAD mesh viewer' if en else 'Lokaler CAD-Netzbetrachter'
    actions=[('zoom-in','+'),('zoom-out','−'),('front','Front'),('top','Top'),('reset','Fit / reset' if en else 'Einpassen / Reset')]
    buttons=''.join(f'<button type="button" data-cad-action="{a}" aria-label="{label if a not in ["zoom-in","zoom-out"] else ("Zoom in" if a=="zoom-in" else "Zoom out")}">{label}</button>' for a,label in actions)
    return head(lang,copy,title+' | Sagar Kriplani',f'/{lang}/cad/')+f'''<main id="main" class="evidence-page cad-page"><div class="library-heading"><a class="text-link" href="/{lang}/gallery/">← {'Academic gallery' if en else 'Akademische Galerie'}</a><p class="eyebrow">LOCAL FILE / PRIVATE VIEWING</p><h1>{'Your mesh.<br>Your device.' if en else 'Ihr Netz.<br>Ihr Gerät.'}</h1><p>{'Open an STL or OBJ mesh directly from your computer. Rotate, pan, zoom and inspect it here. The file stays in this browser tab: it is not uploaded, published, stored or sent to a server.' if en else 'STL- oder OBJ-Netze direkt vom Computer öffnen, drehen, verschieben und vergrößern. Die Datei bleibt in diesem Browser-Tab: kein Upload, keine Veröffentlichung, keine Speicherung und keine Übertragung an einen Server.'}</p></div><div class="cad-toolbar"><label class="button primary" for="cad-file">{'Choose STL / OBJ' if en else 'STL / OBJ auswählen'} ↗</label><input id="cad-file" type="file" accept=".stl,.obj" class="sr-only">{buttons}</div><div class="cad-stage"><canvas id="cad-canvas" tabindex="0" aria-label="{'Interactive mesh: arrow keys rotate, plus and minus zoom, zero resets' if en else 'Interaktives Netz: Pfeiltasten drehen, Plus und Minus vergrößern, Null setzt zurück'}"></canvas></div><p id="cad-status" class="cad-status" role="status" aria-live="polite">{'Loading viewer…' if en else 'Ansicht wird geladen…'}</p><p class="cad-help">{'Drag to orbit · Shift-drag or right-drag to pan · Scroll to zoom · Arrow keys to rotate · 0 to reset. Up to 50 MB / 500,000 triangles. The initial cube is a generic demo, not a portfolio project. Mesh units are not inferred, and this is not a measurement tool.' if en else 'Ziehen zum Drehen · Umschalt-Ziehen oder rechts ziehen zum Verschieben · Scrollen zum Zoomen · Pfeiltasten zum Drehen · 0 für Reset. Bis 50 MB / 500.000 Dreiecke. Der anfängliche Würfel ist eine Demo, kein Portfolioprojekt. Netzeinheiten werden nicht abgeleitet; dies ist kein Messwerkzeug.'}</p><noscript><p>{'JavaScript is required for the local 3D viewer. The academic image gallery works without JavaScript.' if en else 'Der lokale 3D-Betrachter benötigt JavaScript. Die akademische Bildergalerie funktioniert auch ohne JavaScript.'}</p></noscript><section class="transcript-section"><h2>{'From native CAD to a viewable mesh' if en else 'Von nativen CAD-Daten zum Netz'}</h2><div class="cad-guides"><article><h3>Autodesk Inventor · .ipt / .iam</h3><p>{'Open the part or complete assembly in Inventor, then export STL or OBJ. For assemblies choose one file if you want the whole assembly together. Mesh exports preserve visible geometry, not the feature tree or assembly constraints.' if en else 'Bauteil oder vollständige Baugruppe in Inventor öffnen und als STL oder OBJ exportieren. Für eine gemeinsame Baugruppenansicht eine Datei wählen. Netzexporte enthalten sichtbare Geometrie, keinen Featurebaum oder Baugruppenabhängigkeiten.'}</p><a href="https://help.autodesk.com/cloudhelp/2025/ENU/Inventor-Help/files/GUID-4EE5D88C-E6B9-48BB-9CC5-7CC7098FF473.htm">{'Autodesk export formats' if en else 'Autodesk-Exportformate'} ↗</a></article><article><h3>FreeCAD · STEP / .FCStd</h3><p>{'Open your permitted STEP/FreeCAD model, select the shapes, and use File → Export → STL or OBJ. For smooth curves use a suitable mesh deviation. Native STEP, Inventor and FreeCAD source files are not parsed by this browser viewer.' if en else 'Freigegebenes STEP-/FreeCAD-Modell öffnen, Körper auswählen und Datei → Exportieren → STL oder OBJ verwenden. Für glatte Kurven eine geeignete Netzabweichung wählen. Native STEP-, Inventor- und FreeCAD-Dateien werden in diesem Browserbetrachter nicht eingelesen.'}</p><a href="https://github.com/FreeCAD/FreeCAD-documentation/blob/main/wiki/Export_to_STL_or_OBJ.md">{'FreeCAD mesh-export guide' if en else 'FreeCAD-Anleitung zum Netzexport'} ↗</a></article></div></section></main><script src="/assets/cad-viewer.js" defer></script>'''+footer(lang,copy)
